17	package org.springframework.boot.logging;
18	
19	import java.io.File;
20	import java.util.Properties;
21	
22	import org.jspecify.annotations.Nullable;
23	
24	import org.springframework.core.env.Environment;
25	import org.springframework.core.env.PropertyResolver;
26	import org.springframework.util.Assert;
27	import org.springframework.util.StringUtils;
28	
29	/**
30	 * A reference to a log output file. Log output files are specified using
31	 * {@code logging.file.name} or {@code logging.file.path} {@link Environment} properties.
32	 * If the {@code logging.file.name} property is not specified {@code "spring.log"} will be
33	 * written in the {@code logging.file.path} directory.
34	 *
35	 * @author Phillip Webb
36	 * @author Christian Carriere-Tisseur
37	 * @since 1.2.1
38	 * @see #get(PropertyResolver)
39	 */
40	public class LogFile {
41	
42		/**
43		 * The name of the Spring property that contains the name of the log file. Names can
44		 * be an exact location or relative to the current directory.
45		 * @since 2.2.0
46		 */
47		public static final String FILE_NAME_PROPERTY = "logging.file.name";
48	
49		/**
50		 * The name of the Spring property that contains the directory where log files are
51		 * written.
52		 * @since 2.2.0
53		 */
54		public static final String FILE_PATH_PROPERTY = "logging.file.path";
55	
56		private final @Nullable String file;
57	
58		private final @Nullable String path;
59	
60		/**
61		 * Create a new {@link LogFile} instance.
62		 * @param file a reference to the file to write
63		 */
64		LogFile(String file) {
65			this(file, null);
66		}
67	
68		/**
69		 * Create a new {@link LogFile} instance.
70		 * @param file a reference to the file to write
71		 * @param path a reference to the logging path to use if {@code file} is not specified
72		 */
73		LogFile(@Nullable String file, @Nullable String path) {
74			Assert.isTrue(StringUtils.hasLength(file) || StringUtils.hasLength(path), "'file' or 'path' must not be empty");
75			this.file = file;
76			this.path = path;
77		}
78	
79		/**
80		 * Apply log file details to {@code LOG_PATH} and {@code LOG_FILE} system properties.
81		 */
82		public void applyToSystemProperties() {
83			applyTo(System.getProperties());
84		}
85	
86		/**
87		 * Apply log file details to {@code LOG_PATH} and {@code LOG_FILE} map entries.
88		 * @param properties the properties to apply to
89		 */
90		public void applyTo(Properties properties) {
91			put(properties, LoggingSystemProperty.LOG_PATH, this.path);
92			put(properties, LoggingSystemProperty.LOG_FILE, toString());
93		}
94	
95		private void put(Properties properties, LoggingSystemProperty property, @Nullable String value) {
96			if (StringUtils.hasLength(value)) {
97				properties.put(property.getEnvironmentVariableName(), value);
98			}
99		}
100	
101		@Override
102		public String toString() {
103			if (StringUtils.hasLength(this.file)) {
104				return this.file;
105			}
106			return new File(this.path, "spring.log").getPath();
107		}
108	
109		/**
110		 * Get a {@link LogFile} from the given Spring {@link Environment}.
111		 * @param propertyResolver the {@link PropertyResolver} used to obtain the logging
112		 * properties
113		 * @return a {@link LogFile} or {@code null} if the environment didn't contain any
114		 * suitable properties
115		 */
116		public static @Nullable LogFile get(PropertyResolver propertyResolver) {
117			String file = propertyResolver.getProperty(FILE_NAME_PROPERTY);
118			String path = propertyResolver.getProperty(FILE_PATH_PROPERTY);
119			if (StringUtils.hasLength(file) || StringUtils.hasLength(path)) {
120				return new LogFile(file, path);
121			}
122			return null;
123		}
124	
125	}
