299					null);
300		}
301	
302		/**
303		 * Return a {@link StandardStackTracePrinter} that prints the stack trace with the
304		 * root exception first (the opposite of {@link Throwable#printStackTrace()}).
305		 * @return a {@link StandardStackTracePrinter} that prints the stack trace root first
306		 */
307		public static StandardStackTracePrinter rootFirst() {
