312		/**
313		 * Options supported by this printer.
314		 */
315		private enum Option {
316	
317			ROOT_FIRST, SHOW_COMMON_FRAMES, HIDE_SUPPRESSED
318	
319		}
320	
321		/**
322		 * Prints the actual line output.
323		 */
324		private record Print(String indent, String caption, Output output) {
325	
326			void circularReference(String hashPrefix, String throwable) throws IOException {
327				this.output.println(this.indent, this.caption + "[CIRCULAR REFERENCE: " + hashPrefix + throwable + "]");
328			}
329	
330			void thrown(String hashPrefix, String throwable) throws IOException {
331				this.output.println(this.indent, this.caption + hashPrefix + throwable);
332			}
333	
334			void at(String frame) throws IOException {
335				this.output.println(this.indent, "\tat " + frame);
336			}
337	
338			void omittedFilteredFrames(int filteredFrameCount) throws IOException {
339				if (filteredFrameCount > 0) {
340					this.output.println(this.indent, "\t... " + filteredFrameCount + " filtered");
341				}
342			}
343	
344			void omittedCommonFrames(int commonFrameCount) throws IOException {
345				this.output.println(this.indent, "\t... " + commonFrameCount + " more");
346			}
347	
348			Print withCausedByCaption(@Nullable StackTrace causedBy) {
349				return withCaption(causedBy != null, "", "Caused by: ");
350			}
351	
352			Print withWrappedByCaption(@Nullable StackTrace wrappedBy) {
353				return withCaption(wrappedBy != null, "", "Wrapped by: ");
354			}
355	
356			public Print withSuppressedCaption() {
357				return withCaption(true, "\t", "Suppressed: ");
358			}
359	
360			private Print withCaption(boolean test, String extraIndent, String caption) {
361				return (test) ? new Print(this.indent + extraIndent, caption, this.output) : this;
362			}
363	
364		}
365	
366		/**
367		 * Line-by-line output.
368		 */
369		private class Output {
370	
371			private static final String ELLIPSIS = "...";
372	
373			private final Appendable out;
374	
375			private int remaining;
376	
377			Output(Appendable out) {
378				this.out = out;
379				this.remaining = StandardStackTracePrinter.this.maximumLength - ELLIPSIS.length();
380			}
381	
382			void println(String indent, String string) throws IOException {
383				if (this.remaining > 0) {
384					String line = indent + string + StandardStackTracePrinter.this.lineSeparator;
385					if (line.length() > this.remaining) {
386						line = line.substring(0, this.remaining) + ELLIPSIS;
387					}
388					this.out.append(line);
389					this.remaining -= line.length();
390				}
391			}
392	
393		}
