395		/**
396		 * Holds the stacktrace for a specific throwable and caches things that are expensive
397		 * to calculate.
398		 */
399		private static final class StackTrace {
400	
401			private final Throwable throwable;
402	
403			private final StackTraceElement @Nullable [] frames;
404	
405			private StackTrace @Nullable [] suppressed;
406	
407			private @Nullable StackTrace cause;
408	
409			private @Nullable Integer hash;
410	
411			private @Nullable String hashPrefix;
412	
413			private StackTrace(Throwable throwable) {
414				this.throwable = throwable;
415				this.frames = (throwable != null) ? throwable.getStackTrace() : null;
416			}
417	
418			Throwable throwable() {
419				return this.throwable;
420			}
421	
422			StackTraceElement @Nullable [] frames() {
423				return this.frames;
424			}
425	
426			int commonFramesCount(@Nullable StackTrace other) {
427				if (other == null || this.frames == null || other.frames == null) {
428					return 0;
429				}
430				int index = this.frames.length - 1;
431				int otherIndex = other.frames.length - 1;
432				while (index >= 0 && otherIndex >= 0 && this.frames[index].equals(other.frames[otherIndex])) {
433					index--;
434					otherIndex--;
435				}
436				return this.frames.length - 1 - index;
437			}
438	
439			StackTrace @Nullable [] suppressed() {
440				if (this.suppressed == null && this.throwable != null) {
441					this.suppressed = Arrays.stream(this.throwable.getSuppressed())
442						.map(StackTrace::new)
443						.toArray(StackTrace[]::new);
444				}
445				return this.suppressed;
446			}
447	
448			@Nullable StackTrace cause() {
449				if (this.cause == null && this.throwable != null) {
450					Throwable cause = this.throwable.getCause();
451					this.cause = (cause != null) ? new StackTrace(cause) : null;
452				}
453				return this.cause;
454			}
455	
456			String hashPrefix(@Nullable ToIntFunction<StackTraceElement> frameHasher) {
457				if (frameHasher == null || throwable() == null) {
458					return "";
459				}
460				this.hashPrefix = (this.hashPrefix != null) ? this.hashPrefix
461						: String.format("<#%08x> ", hash(new HashSet<>(), frameHasher));
462				return this.hashPrefix;
463			}
464	
465			private int hash(HashSet<Throwable> seen, ToIntFunction<StackTraceElement> frameHasher) {
466				if (this.hash != null) {
467					return this.hash;
468				}
469				int hash = 0;
470				StackTrace cause = cause();
471				if (cause != null && seen.add(cause.throwable())) {
472					hash = cause.hash(seen, frameHasher);
473				}
474				hash = 31 * hash + throwable().getClass().getName().hashCode();
475				if (frames() != null) {
476					for (StackTraceElement frame : frames()) {
477						hash = 31 * hash + frameHasher.applyAsInt(frame);
478					}
479				}
480				this.hash = hash;
481				return hash;
482			}
483	
484		}
485	
486	}
