18	
19	import java.util.ArrayList;
20	import java.util.Arrays;
21	import java.util.Collections;
22	import java.util.HashMap;
23	import java.util.List;
24	import java.util.Locale;
25	import java.util.Map;
26	
27	import ch.qos.logback.classic.Level;
28	import ch.qos.logback.classic.spi.ILoggingEvent;
29	import ch.qos.logback.core.pattern.CompositeConverter;
30	
31	import org.springframework.boot.ansi.AnsiBackground;
32	import org.springframework.boot.ansi.AnsiColor;
33	import org.springframework.boot.ansi.AnsiElement;
34	import org.springframework.boot.ansi.AnsiOutput;
35	import org.springframework.boot.ansi.AnsiStyle;
36	
37	/**
38	 * Logback {@link CompositeConverter} to color output using the {@link AnsiOutput} class.
39	 * One or more styling options can be provided to the converter, or if not specified color
40	 * will be picked based on the logging level. Supported options include foreground colors
41	 * (e.g. {@code red}, {@code bright_blue}), background colors (e.g. {@code bg_red},
42	 * {@code bg_bright_green}), and text styles (e.g. {@code bold}, {@code underline},
43	 * {@code reverse}).
44	 *
45	 * @author Phillip Webb
46	 * @since 1.0.0
47	 */
48	public class ColorConverter extends CompositeConverter<ILoggingEvent> {
49	
50		private static final Map<String, AnsiElement> ELEMENTS;
51	
52		static {
53			Map<String, AnsiElement> ansiElements = new HashMap<>();
54			Arrays.stream(AnsiColor.values())
55				.filter((color) -> color != AnsiColor.DEFAULT)
56				.forEach((color) -> ansiElements.put(color.name().toLowerCase(Locale.ROOT), color));
57			Arrays.stream(AnsiStyle.values())
58				.forEach((style) -> ansiElements.put(style.name().toLowerCase(Locale.ROOT), style));
59			Arrays.stream(AnsiBackground.values())
60				.filter((bg) -> bg != AnsiBackground.DEFAULT)
61				.forEach((bg) -> ansiElements.put("bg_" + bg.name().toLowerCase(Locale.ROOT), bg));
62			ELEMENTS = Collections.unmodifiableMap(ansiElements);
63		}
64	
65		private static final Map<Integer, AnsiElement> LEVELS;
66	
67		static {
68			Map<Integer, AnsiElement> ansiLevels = new HashMap<>();
69			ansiLevels.put(Level.ERROR_INTEGER, AnsiColor.RED);
70			ansiLevels.put(Level.WARN_INTEGER, AnsiColor.YELLOW);
71			LEVELS = Collections.unmodifiableMap(ansiLevels);
72		}
73	
74		@Override
75		protected String transform(ILoggingEvent event, String in) {
76			List<String> options = getOptionList();
77			List<AnsiElement> elements = new ArrayList<>();
78			if (options != null) {
79				for (String option : options) {
80					String[] optionParts = option.split(",");
81					for (String optionPart : optionParts) {
82						AnsiElement element = ELEMENTS.get(optionPart.trim().toLowerCase(Locale.ROOT));
83						if (element != null) {
84							elements.add(element);
85						}
86					}
87				}
88			}
89			if (elements.isEmpty()) {
90				// Assume highlighting
91				AnsiElement element = LEVELS.get(event.getLevel().toInteger());
92				elements.add((element != null) ? element : AnsiColor.GREEN);
93			}
94			return toAnsiString(in, elements.toArray(new AnsiElement[0]));
95		}
96	
97		protected String toAnsiString(String in, AnsiElement element) {
98			return AnsiOutput.toString(element, in);
99		}
100	
101		protected String toAnsiString(String in, AnsiElement... elements) {
102			Object[] ansiParams = new Object[elements.length + 1];
103			System.arraycopy(elements, 0, ansiParams, 0, elements.length);
104			ansiParams[elements.length] = in;
105			return AnsiOutput.toString(ansiParams);
106		}
107	
108		static String getName(AnsiElement element) {
109			return ELEMENTS.entrySet()
110				.stream()
111				.filter((entry) -> entry.getValue().equals(element))
112				.map(Map.Entry::getKey)
113				.findFirst()
114				.orElseThrow();
115		}
116	
117	}
