18	
19	import java.util.ArrayList;
20	import java.util.Arrays;
21	import java.util.Collections;
22	import java.util.HashMap;
23	import java.util.List;
24	import java.util.Locale;
25	import java.util.Map;
26	
27	import org.apache.logging.log4j.Level;
28	import org.apache.logging.log4j.core.LogEvent;
29	import org.apache.logging.log4j.core.config.Configuration;
30	import org.apache.logging.log4j.core.config.plugins.Plugin;
31	import org.apache.logging.log4j.core.layout.PatternLayout;
32	import org.apache.logging.log4j.core.pattern.ConverterKeys;
33	import org.apache.logging.log4j.core.pattern.LogEventPatternConverter;
34	import org.apache.logging.log4j.core.pattern.PatternConverter;
35	import org.apache.logging.log4j.core.pattern.PatternFormatter;
36	import org.apache.logging.log4j.core.pattern.PatternParser;
37	import org.jspecify.annotations.Nullable;
38	
39	import org.springframework.boot.ansi.AnsiBackground;
40	import org.springframework.boot.ansi.AnsiColor;
41	import org.springframework.boot.ansi.AnsiElement;
42	import org.springframework.boot.ansi.AnsiOutput;
43	import org.springframework.boot.ansi.AnsiStyle;
