45	/**
46	 * Log4j2 {@link LogEventPatternConverter} to color output using the {@link AnsiOutput}
47	 * class. One or more styling options can be provided to the converter, or if not
48	 * specified color styling will be picked based on the logging level. Supported options
49	 * include foreground colors (e.g. {@code red}, {@code bright_blue}), background colors
50	 * (e.g. {@code bg_red}, {@code bg_bright_green}), and text styles (e.g. {@code bold},
51	 * {@code underline}, {@code reverse}).
52	 *
53	 * @author Vladimir Tsanev
54	 * @since 1.3.0
55	 */
56	@Plugin(name = "color", category = PatternConverter.CATEGORY)
57	@ConverterKeys({ "clr", "color" })
58	public final class ColorConverter extends LogEventPatternConverter {
59	
60		private static final Map<String, AnsiElement> ELEMENTS;
61	
62		static {
63			Map<String, AnsiElement> ansiElements = new HashMap<>();
64			Arrays.stream(AnsiColor.values())
65				.filter((color) -> color != AnsiColor.DEFAULT)
66				.forEach((color) -> ansiElements.put(color.name().toLowerCase(Locale.ROOT), color));
67			Arrays.stream(AnsiStyle.values())
68				.forEach((style) -> ansiElements.put(style.name().toLowerCase(Locale.ROOT), style));
69			Arrays.stream(AnsiBackground.values())
70				.filter((bg) -> bg != AnsiBackground.DEFAULT)
71				.forEach((bg) -> ansiElements.put("bg_" + bg.name().toLowerCase(Locale.ROOT), bg));
72			ELEMENTS = Collections.unmodifiableMap(ansiElements);
73		}
74	
75		private static final Map<Integer, AnsiElement> LEVELS;
76	
77		static {
78			Map<Integer, AnsiElement> ansiLevels = new HashMap<>();
79			ansiLevels.put(Level.FATAL.intLevel(), AnsiColor.RED);
80			ansiLevels.put(Level.ERROR.intLevel(), AnsiColor.RED);
81			ansiLevels.put(Level.WARN.intLevel(), AnsiColor.YELLOW);
82			LEVELS = Collections.unmodifiableMap(ansiLevels);
83		}
84	
85		private final List<PatternFormatter> formatters;
86	
87		private final List<AnsiElement> stylings;
88	
89		private ColorConverter(List<PatternFormatter> formatters, List<AnsiElement> stylings) {
90			super("style", "style");
91			this.formatters = formatters;
92			this.stylings = stylings;
93		}
94	
95		@Override
96		public boolean handlesThrowable() {
97			for (PatternFormatter formatter : this.formatters) {
98				if (formatter.handlesThrowable()) {
99					return true;
100				}
101			}
102			return super.handlesThrowable();
103		}
104	
105		@Override
106		public void format(LogEvent event, StringBuilder toAppendTo) {
107			StringBuilder buf = new StringBuilder();
108			for (PatternFormatter formatter : this.formatters) {
109				formatter.format(event, buf);
110			}
111			if (!buf.isEmpty()) {
112				if (this.stylings.isEmpty()) {
113					// Assume highlighting
114					AnsiElement element = LEVELS.get(event.getLevel().intLevel());
115					element = (element != null) ? element : AnsiColor.GREEN;
116					appendAnsiString(toAppendTo, buf.toString(), element);
117				}
118				else {
119					appendAnsiString(toAppendTo, buf.toString(), this.stylings.toArray(new AnsiElement[0]));
120				}
121			}
122		}
123	
124		private void appendAnsiString(StringBuilder toAppendTo, String in, AnsiElement element) {
125			toAppendTo.append(AnsiOutput.toString(element, in));
126		}
127	
128		protected void appendAnsiString(StringBuilder toAppendTo, String in, AnsiElement... elements) {
129			Object[] ansiParams = new Object[elements.length + 1];
130			System.arraycopy(elements, 0, ansiParams, 0, elements.length);
131			ansiParams[elements.length] = in;
132			toAppendTo.append(AnsiOutput.toString(ansiParams));
133		}
134	
135		/**
136		 * Creates a new instance of the class. Required by Log4J2.
137		 * @param config the configuration
138		 * @param options the options
139		 * @return a new instance, or {@code null} if the options are invalid
140		 */
141		public static @Nullable ColorConverter newInstance(@Nullable Configuration config, @Nullable String[] options) {
142			if (options.length < 1) {
143				LOGGER.error("Incorrect number of options on style. Expected at least 1, received {}", options.length);
144				return null;
145			}
146			if (options[0] == null) {
147				LOGGER.error("No pattern supplied on style");
148				return null;
149			}
150			PatternParser parser = PatternLayout.createPatternParser(config);
151			List<PatternFormatter> formatters = parser.parse(options[0]);
152			List<AnsiElement> stylings = new ArrayList<>();
153			if (options.length >= 2 && options[1] != null) {
154				String[] optionParts = options[1].split(",");
155				for (String optionPart : optionParts) {
156					AnsiElement element = ELEMENTS.get(optionPart.trim().toLowerCase(Locale.ROOT));
157					if (element != null) {
158						stylings.add(element);
159					}
160				}
161			}
162			return new ColorConverter(formatters, stylings);
163		}
164	
165	}
