129			setSystemProperty(LoggingSystemProperty.APPLICATION_GROUP, resolver);
130			setSystemProperty(LoggingSystemProperty.PID, new ApplicationPid().toString());
131			setSystemProperty(LoggingSystemProperty.CONSOLE_CHARSET, resolver, getDefaultConsoleCharset().name());
132			setSystemProperty(LoggingSystemProperty.FILE_CHARSET, resolver, getDefaultFileCharset().name());
133			setSystemProperty(LoggingSystemProperty.CONSOLE_THRESHOLD, resolver, this::thresholdMapper);
134			setSystemProperty(LoggingSystemProperty.FILE_THRESHOLD, resolver, this::thresholdMapper);
135			setSystemProperty(LoggingSystemProperty.EXCEPTION_CONVERSION_WORD, resolver);
136			setSystemProperty(LoggingSystemProperty.CONSOLE_PATTERN, resolver);
137			setSystemProperty(LoggingSystemProperty.FILE_PATTERN, resolver);
138			setSystemProperty(LoggingSystemProperty.CONSOLE_STRUCTURED_FORMAT, resolver);
139			setSystemProperty(LoggingSystemProperty.FILE_STRUCTURED_FORMAT, resolver);
140			setSystemProperty(LoggingSystemProperty.LEVEL_PATTERN, resolver);
141			setSystemProperty(LoggingSystemProperty.DATEFORMAT_PATTERN, resolver);
142			setSystemProperty(LoggingSystemProperty.CORRELATION_PATTERN, resolver);
143			if (logFile != null) {
144				logFile.applyToSystemProperties();
145			}
146			if (!this.environment.getProperty("logging.console.enabled", Boolean.class, true)) {
147				setSystemProperty(LoggingSystemProperty.CONSOLE_THRESHOLD.getEnvironmentVariableName(), "OFF");
148			}
149		}
150	
151		/**
152		 * Returns the default console charset.
153		 * @return the default console charset
154		 * @since 3.5.0
155		 */
156		protected Charset getDefaultConsoleCharset() {
157			Console console = getConsole();
158			return (console != null) ? console.charset() : Charset.defaultCharset();
159		}
160	
161		/**
162		 * Returns the default file charset.
163		 * @return the default file charset
164		 * @since 3.5.0
165		 */
166		protected Charset getDefaultFileCharset() {
167			return StandardCharsets.UTF_8;
168		}
169	
170		private void setSystemProperty(LoggingSystemProperty property, PropertyResolver resolver) {
171			setSystemProperty(property, resolver, (i) -> i);
172		}
173	
174		private void setSystemProperty(LoggingSystemProperty property, PropertyResolver resolver,
175				Function<@Nullable String, @Nullable String> mapper) {
176			setSystemProperty(property, resolver, null, mapper);
177		}
178	
179		private void setSystemProperty(LoggingSystemProperty property, PropertyResolver resolver, String defaultValue) {
180			setSystemProperty(property, resolver, defaultValue, (i) -> i);
181		}
182	
183		private void setSystemProperty(LoggingSystemProperty property, PropertyResolver resolver,
184				@Nullable String defaultValue, Function<@Nullable String, @Nullable String> mapper) {
185			if (property.getIncludePropertyName() != null) {
186				if (!resolver.getProperty(property.getIncludePropertyName(), Boolean.class, Boolean.TRUE)) {
187					return;
188				}
189			}
190			String applicationPropertyName = property.getApplicationPropertyName();
191			String value = (applicationPropertyName != null) ? resolver.getProperty(applicationPropertyName) : null;
192			value = (value != null) ? value : this.defaultValueResolver.apply(applicationPropertyName);
193			value = (value != null) ? value : defaultValue;
194			value = mapper.apply(value);
195			setSystemProperty(property.getEnvironmentVariableName(), value);
196			if (property == LoggingSystemProperty.APPLICATION_NAME && StringUtils.hasText(value)) {
197				// LOGGED_APPLICATION_NAME is deprecated for removal in 4.0.0
198				setSystemProperty("LOGGED_APPLICATION_NAME", "[%s] ".formatted(value));
199			}
200		}
201	
202		private void setSystemProperty(LoggingSystemProperty property, String value) {
203			setSystemProperty(property.getEnvironmentVariableName(), value);
204		}
205	
206		private @Nullable String thresholdMapper(@Nullable String input) {
207			// YAML converts an unquoted OFF to false
208			if ("false".equals(input)) {
209				return "OFF";
210			}
211			return input;
212		}
213	
214		/**
215		 * Set a system property.
216		 * @param name the property name
217		 * @param value the value
218		 */
219		protected final void setSystemProperty(String name, @Nullable String value) {
220			this.setter.accept(name, value);
221		}
222	
223	}
