28	/**
29	 * Base class for {@link StructuredLogFormatter} implementations that generates JSON using
30	 * a {@link JsonWriter}.
31	 *
32	 * @param <E> the log event type
33	 * @author Phillip Webb
34	 * @since 3.4.0
35	 */
36	public abstract class JsonWriterStructuredLogFormatter<E> implements StructuredLogFormatter<E> {
37	
38		private final JsonWriter<E> jsonWriter;
39	
40		/**
41		 * Create a new {@link JsonWriterStructuredLogFormatter} instance with the given
42		 * members.
43		 * @param members a consumer, which should configure the members
44		 * @param customizer an optional customizer to apply
45		 */
46		protected JsonWriterStructuredLogFormatter(Consumer<Members<E>> members,
47				@Nullable StructuredLoggingJsonMembersCustomizer<?> customizer) {
48			this(JsonWriter.of(customized(members, customizer)).withNewLineAtEnd());
49		}
50	
51		private static <E> Consumer<Members<E>> customized(Consumer<Members<E>> members,
52				@Nullable StructuredLoggingJsonMembersCustomizer<?> customizer) {
53			return (customizer != null) ? members.andThen(customizeWith(customizer)) : members;
54		}
55	
56		@SuppressWarnings("unchecked")
57		private static <E> Consumer<Members<E>> customizeWith(StructuredLoggingJsonMembersCustomizer<?> customizer) {
58			return (members) -> LambdaSafe.callback(StructuredLoggingJsonMembersCustomizer.class, customizer, members)
59				.invoke((instance) -> instance.customize(members));
60		}
61	
62		/**
63		 * Create a new {@link JsonWriterStructuredLogFormatter} instance with the given
64		 * {@link JsonWriter}.
65		 * @param jsonWriter the {@link JsonWriter}
66		 */
67		protected JsonWriterStructuredLogFormatter(JsonWriter<E> jsonWriter) {
68			this.jsonWriter = jsonWriter;
69		}
70	
71		@Override
72		public String format(E event) {
73			return this.jsonWriter.writeToString(event);
74		}
75	
76		@Override
77		public byte[] formatAsBytes(E event, Charset charset) {
78			return this.jsonWriter.write(event).toByteArray(charset);
79		}
80	
81	}
