28	/**
29	 * Functions to extract items from {@link ILoggingEvent}.
30	 *
31	 * @author Phillip Webb
32	 */
33	class Extractor {
34	
35		private final @Nullable StackTracePrinter stackTracePrinter;
36	
37		private final ThrowableProxyConverter throwableProxyConverter;
38	
39		Extractor(@Nullable StackTracePrinter stackTracePrinter, ThrowableProxyConverter throwableProxyConverter) {
40			this.stackTracePrinter = stackTracePrinter;
41			this.throwableProxyConverter = throwableProxyConverter;
42		}
43	
44		String messageAndStackTrace(ILoggingEvent event) {
45			return event.getFormattedMessage() + "\n\n" + stackTrace(event);
46		}
47	
48		String stackTrace(ILoggingEvent event) {
49			if (this.stackTracePrinter != null) {
50				IThrowableProxy throwableProxy = event.getThrowableProxy();
51				Assert.state(throwableProxy instanceof ThrowableProxy,
52						"Instance must be a ThrowableProxy in order to print exception");
53				Throwable throwable = ((ThrowableProxy) throwableProxy).getThrowable();
54				return this.stackTracePrinter.printStackTraceToString(throwable);
55			}
56			return this.throwableProxyConverter.convert(event);
57		}
