196			if (!initializeFromAotGeneratedArtifactsIfPossible(initializationContext, logFile)) {
197				super.initialize(initializationContext, configLocation, logFile);
198			}
199			loggerContext.getTurboFilterList().remove(SUPPRESS_ALL_FILTER);
