207		private boolean initializeFromAotGeneratedArtifactsIfPossible(LoggingInitializationContext initializationContext,
208				@Nullable LogFile logFile) {
209			if (!AotDetector.useGeneratedArtifacts()) {
210				return false;
211			}
212			if (initializationContext != null) {
213				Environment environment = initializationContext.getEnvironment();
214				Assert.state(environment != null, "'environment' must not be null");
215				applySystemProperties(environment, logFile);
216			}
217			LoggerContext loggerContext = getLoggerContext();
218			stopAndReset(loggerContext);
219			withLoggingSuppressed(() -> putInitializationContextObjects(loggerContext, initializationContext));
220			SystemStatusListener.addTo(loggerContext);
221			SpringBootJoranConfigurator configurator = new SpringBootJoranConfigurator(initializationContext);
222			configurator.setContext(loggerContext);
223			boolean configuredUsingAotGeneratedArtifacts = configurator.configureUsingAotGeneratedArtifacts();
224			if (configuredUsingAotGeneratedArtifacts) {
225				reportConfigurationErrorsIfNecessary(loggerContext);
226			}
227			return configuredUsingAotGeneratedArtifacts;
228		}
