232			LoggerContext loggerContext = getLoggerContext();
233			stopAndReset(loggerContext);
234			withLoggingSuppressed(() -> {
235				boolean debug = Boolean.getBoolean("logback.debug");
236				putInitializationContextObjects(loggerContext, initializationContext);
237				SystemStatusListener.addTo(loggerContext, debug);
238				Environment environment = initializationContext.getEnvironment();
239				Assert.state(environment != null, "'environment' must not be null");
240				// Apply system properties directly in case the same JVM runs multiple apps
241				new LogbackLoggingSystemProperties(environment, getDefaultValueResolver(environment),
242						loggerContext::putProperty)
243					.apply(logFile);
244				LogbackConfigurator configurator = (!debug) ? new LogbackConfigurator(loggerContext)
245						: new DebugLogbackConfigurator(loggerContext);
246				new DefaultLogbackConfiguration(logFile).apply(configurator);
247				loggerContext.setPackagingDataEnabled(true);
248				loggerContext.start();
249			});
250		}
