252		@Override
253		protected void loadConfiguration(LoggingInitializationContext initializationContext, String location,
254				@Nullable LogFile logFile) {
255			LoggerContext loggerContext = getLoggerContext();
256			stopAndReset(loggerContext);
257			withLoggingSuppressed(() -> {
258				putInitializationContextObjects(loggerContext, initializationContext);
259				if (initializationContext != null) {
260					Environment environment = initializationContext.getEnvironment();
261					Assert.state(environment != null, "'environment' must not be null");
262					applySystemProperties(environment, logFile);
263				}
264				SystemStatusListener.addTo(loggerContext);
265				try {
266					Resource resource = ApplicationResourceLoader.get().getResource(location);
267					configureByResourceUrl(initializationContext, loggerContext, resource.getURL());
268				}
269				catch (Exception ex) {
270					throw new IllegalStateException("Could not initialize Logback logging from " + location, ex);
271				}
272				loggerContext.start();
273			});
274			reportConfigurationErrorsIfNecessary(loggerContext);
275		}
