277		private void reportConfigurationErrorsIfNecessary(LoggerContext loggerContext) {
278			StringBuilder errors = new StringBuilder();
279			List<Throwable> suppressedExceptions = new ArrayList<>();
280			for (Status status : loggerContext.getStatusManager().getCopyOfStatusList()) {
281				if (status.getLevel() == Status.ERROR) {
282					errors.append((!errors.isEmpty()) ? String.format("%n") : "");
283					errors.append(status);
284					if (status.getThrowable() != null) {
285						suppressedExceptions.add(status.getThrowable());
286					}
287				}
288			}
289			if (errors.isEmpty()) {
290				if (!StatusUtil.contextHasStatusListener(loggerContext)) {
291					this.statusPrinter.printInCaseOfErrorsOrWarnings(loggerContext);
292				}
293				return;
294			}
295			IllegalStateException ex = new IllegalStateException(
296					String.format("Logback configuration error detected: %n%s", errors));
297			suppressedExceptions.forEach(ex::addSuppressed);
298			throw ex;
299		}
