418		private LoggerContext getLoggerContext() {
419			ILoggerFactory factory = getLoggerFactory();
420			Assert.state(factory instanceof LoggerContext,
421					() -> String.format(
422							"LoggerFactory is not a Logback LoggerContext but Logback is on "
423									+ "the classpath. Either remove Logback or the competing "
424									+ "implementation (%s loaded from %s). If you are using "
425									+ "WebLogic you will need to add 'org.slf4j' to "
426									+ "prefer-application-packages in WEB-INF/weblogic.xml",
427							factory.getClass(), getLocation(factory)));
428			return (LoggerContext) factory;
