431		private ILoggerFactory getLoggerFactory() {
432			ILoggerFactory factory = LoggerFactory.getILoggerFactory();
433			while (factory instanceof SubstituteLoggerFactory) {
434				try {
435					Thread.sleep(50);
436				}
437				catch (InterruptedException ex) {
438					Thread.currentThread().interrupt();
439					throw new IllegalStateException("Interrupted while waiting for non-substitute logger factory", ex);
440				}
441				factory = LoggerFactory.getILoggerFactory();
442			}
443			return factory;
444		}
