446		private Object getLocation(ILoggerFactory factory) {
447			try {
448				ProtectionDomain protectionDomain = factory.getClass().getProtectionDomain();
449				CodeSource codeSource = protectionDomain.getCodeSource();
450				if (codeSource != null) {
451					return codeSource.getLocation();
452				}
453			}
454			catch (SecurityException ex) {
455				// Unable to determine location
456			}
457			return "unknown location";
458		}
