37	/**
38	 * Utility class that can be used to format a correlation identifier for logging based on
39	 * <a href=
40	 * "https://www.w3.org/TR/trace-context/#examples-of-http-traceparent-headers">W3C</a>
41	 * recommendations.
42	 * <p>
43	 * The formatter can be configured with a comma-separated list of names and the expected
44	 * length of their resolved value. Each item should be specified in the form
45	 * {@code "<name>(length)"}. For example, {@code "traceId(32),spanId(16)"} specifies the
46	 * names {@code "traceId"} and {@code "spanId"} with expected lengths of {@code 32} and
47	 * {@code 16} respectively.
48	 * <p>
49	 * Correlation IDs are formatted as dash separated strings surrounded in square brackets.
50	 * Formatted output is always of a fixed width and with trailing space. Dashes are omitted
51	 * if none of the named items can be resolved.
52	 * <p>
53	 * The following example would return a formatted result of
54	 * {@code "[01234567890123456789012345678901-0123456789012345] "}: <pre class="code">
55	 * CorrelationIdFormatter formatter = CorrelationIdFormatter.of("traceId(32),spanId(16)");
56	 * Map&lt;String, String&gt; mdc = Map.of("traceId", "01234567890123456789012345678901", "spanId", "0123456789012345");
57	 * return formatter.format(mdc::get);
58	 * </pre>
59	 * <p>
60	 * If {@link #of(String)} is called with an empty spec the {@link #DEFAULT} formatter will
61	 * be used.
62	 *
63	 * @author Phillip Webb
64	 * @since 3.2.0
65	 * @see #of(String)
66	 * @see #of(Collection)
67	 */
68	public final class CorrelationIdFormatter {
69	
70		/**
71		 * Default {@link CorrelationIdFormatter}.
72		 */
73		public static final CorrelationIdFormatter DEFAULT = CorrelationIdFormatter.of("traceId(32),spanId(16)");
74	
75		private final List<Part> parts;
76	
77		private final String blank;
78	
79		private CorrelationIdFormatter(List<Part> parts) {
80			this.parts = parts;
81			this.blank = String.format("[%s] ", parts.stream().map(Part::blank).collect(Collectors.joining(" ")));
82		}
83	
84		/**
85		 * Format a correlation from the values in the given resolver.
86		 * @param resolver the resolver used to resolve named values
87		 * @return a formatted correlation id
88		 */
89		public String format(UnaryOperator<@Nullable String> resolver) {
90			StringBuilder result = new StringBuilder(this.blank.length());
91			formatTo(resolver, result);
92			return result.toString();
93		}
94	
95		/**
96		 * Format a correlation from the values in the given resolver and append it to the
97		 * given {@link Appendable}.
98		 * @param resolver the resolver used to resolve named values
99		 * @param appendable the appendable for the formatted correlation id
100		 */
101		public void formatTo(UnaryOperator<@Nullable String> resolver, Appendable appendable) {
102			Predicate<Part> canResolve = (part) -> StringUtils.hasLength(resolver.apply(part.name()));
103			try {
104				if (this.parts.stream().anyMatch(canResolve)) {
105					appendable.append('[');
106					for (Iterator<Part> iterator = this.parts.iterator(); iterator.hasNext();) {
107						appendable.append(iterator.next().resolve(resolver));
108						if (iterator.hasNext()) {
109							appendable.append('-');
110						}
111					}
112					appendable.append("] ");
113				}
114				else {
115					appendable.append(this.blank);
116				}
117			}
118			catch (IOException ex) {
119				throw new UncheckedIOException(ex);
120			}
121		}
122	
123		@Override
124		public String toString() {
125			return this.parts.stream().map(Part::toString).collect(Collectors.joining(","));
126		}
127	
128		/**
129		 * Create a new {@link CorrelationIdFormatter} instance from the given specification.
130		 * @param spec a comma-separated specification
131		 * @return a new {@link CorrelationIdFormatter} instance
132		 */
133		public static CorrelationIdFormatter of(@Nullable String spec) {
134			try {
135				return (!StringUtils.hasText(spec)) ? DEFAULT : of(List.of(spec.split(",")));
136			}
137			catch (Exception ex) {
138				throw new IllegalStateException("Unable to parse correlation formatter spec '%s'".formatted(spec), ex);
139			}
140		}
141	
142		/**
143		 * Create a new {@link CorrelationIdFormatter} instance from the given specification.
144		 * @param spec a pre-separated specification
145		 * @return a new {@link CorrelationIdFormatter} instance
146		 */
147		public static CorrelationIdFormatter of(String @Nullable [] spec) {
148			return of((spec != null) ? List.of(spec) : Collections.emptyList());
149		}
150	
151		/**
152		 * Create a new {@link CorrelationIdFormatter} instance from the given specification.
153		 * @param spec a pre-separated specification
154		 * @return a new {@link CorrelationIdFormatter} instance
155		 */
156		public static CorrelationIdFormatter of(Collection<String> spec) {
157			if (CollectionUtils.isEmpty(spec)) {
158				return DEFAULT;
159			}
160			List<Part> parts = spec.stream().map(Part::of).toList();
161			return new CorrelationIdFormatter(parts);
162		}
163	
164		/**
165		 * A part of the correlation id.
166		 *
167		 * @param name the name of the correlation part
168		 * @param length the expected length of the correlation part
169		 */
170		record Part(String name, int length) {
171	
172			private static final Pattern pattern = Pattern.compile("^(.+?)\\((\\d+)\\)$");
173	
174			String resolve(UnaryOperator<@Nullable String> resolver) {
175				String resolved = resolver.apply(name());
176				if (resolved == null) {
177					return blank();
178				}
179				int padding = length() - resolved.length();
180				return (padding <= 0) ? resolved : resolved + " ".repeat(padding);
181			}
182	
183			String blank() {
184				return " ".repeat(this.length);
185			}
186	
187			@Override
188			public String toString() {
189				return "%s(%s)".formatted(name(), length());
190			}
191	
192			static Part of(String part) {
193				Matcher matcher = pattern.matcher(part.trim());
194				Assert.state(matcher.matches(), () -> "Invalid specification part '%s'".formatted(part));
195				String name = matcher.group(1);
196				int length = Integer.parseInt(matcher.group(2));
197				return new Part(name, length);
198			}
199	
200		}
201	
202	}
