150		static final class LogbackConfigurationAotContribution implements BeanFactoryInitializationAotContribution {
151	
152			private final ModelWriter modelWriter;
153	
154			private final PatternRules patternRules;
155	
156			private LogbackConfigurationAotContribution(Model model, ModelInterpretationContext interpretationContext,
157					Context context) {
158				this.modelWriter = new ModelWriter(model, interpretationContext);
159				this.patternRules = new PatternRules(context);
160			}
161	
162			@Override
163			public void applyTo(GenerationContext generationContext,
164					BeanFactoryInitializationCode beanFactoryInitializationCode) {
165				this.modelWriter.writeTo(generationContext);
166				this.patternRules.save(generationContext);
167			}
