170	
171		private static final class ModelWriter {
172	
173			private static final String MODEL_RESOURCE_LOCATION = "META-INF/spring/logback-model";
174	
175			private final Model model;
176	
177			private final ModelInterpretationContext modelInterpretationContext;
178	
179			private ModelWriter(Model model, ModelInterpretationContext modelInterpretationContext) {
180				this.model = model;
181				this.modelInterpretationContext = modelInterpretationContext;
182			}
183	
184			private void writeTo(GenerationContext generationContext) {
185				byte[] serializedModel = serializeModel();
186				generationContext.getGeneratedFiles()
187					.handleFile(Kind.RESOURCE, MODEL_RESOURCE_LOCATION,
188							new RequireNewOrMatchingContentFileHandler(serializedModel));
189				generationContext.getRuntimeHints().resources().registerPattern(MODEL_RESOURCE_LOCATION);
190				ReflectionHints reflectionHints = generationContext.getRuntimeHints().reflection();
191				serializationTypes(this.model).forEach(reflectionHints::registerJavaSerialization);
192				reflectionTypes(this.model).forEach((type) -> generationContext.getRuntimeHints()
193					.reflection()
194					.registerType(TypeReference.of(type), MemberCategory.INVOKE_PUBLIC_METHODS,
195							MemberCategory.INVOKE_PUBLIC_CONSTRUCTORS));
196			}
197	
198			private byte[] serializeModel() {
199				ByteArrayOutputStream bytes = new ByteArrayOutputStream();
200				try (ObjectOutputStream output = new ObjectOutputStream(bytes)) {
201					output.writeObject(this.model);
202				}
203				catch (IOException ex) {
204					throw new RuntimeException(ex);
205				}
206				return bytes.toByteArray();
207			}
208	
209			@SuppressWarnings("unchecked")
210			private Set<Class<? extends Serializable>> serializationTypes(Model model) {
211				Set<Class<? extends Serializable>> modelClasses = new HashSet<>();
212				Class<?> candidate = model.getClass();
213				while (Model.class.isAssignableFrom(candidate)) {
214					if (modelClasses.add((Class<? extends Model>) candidate)) {
215						ReflectionUtils.doWithFields(candidate, (field) -> {
216							if (Modifier.isStatic(field.getModifiers())) {
217								return;
218							}
219							ReflectionUtils.makeAccessible(field);
220							Object value = field.get(model);
221							if (value != null) {
222								Class<?> fieldType = value.getClass();
223								if (Serializable.class.isAssignableFrom(fieldType)) {
224									modelClasses.add((Class<? extends Serializable>) fieldType);
225								}
226							}
227						});
228						candidate = candidate.getSuperclass();
229					}
230				}
231				for (Model submodel : model.getSubModels()) {
232					modelClasses.addAll(serializationTypes(submodel));
233				}
234				return modelClasses;
235			}
236	
237			private Set<Class<?>> reflectionTypes(Model model) {
238				return reflectionTypes(model, () -> null);
239			}
240	
241			private Set<Class<?>> reflectionTypes(Model model, Supplier<Object> parent) {
242				Set<Class<?>> reflectionTypes = new HashSet<>();
243				Class<?> componentType = determineType(model, parent);
244				if (componentType != null) {
245					processComponent(componentType, reflectionTypes);
246				}
247				Supplier<Object> componentSupplier = SingletonSupplier.of(() -> instantiate(componentType));
248				for (Model submodel : model.getSubModels()) {
249					reflectionTypes.addAll(reflectionTypes(submodel, componentSupplier));
250				}

250				}
251				return reflectionTypes;
252			}
253	
254			private @Nullable Class<?> determineType(Model model, Supplier<Object> parentSupplier) {
255				String className = (model instanceof ComponentModel componentModel) ? componentModel.getClassName() : null;
256				if (className != null) {
257					return loadImportType(className);
258				}
259				String tag = model.getTag();
260				if (tag != null) {
261					className = this.modelInterpretationContext.getDefaultNestedComponentRegistry()
262						.findDefaultComponentTypeByTag(tag);
263					if (className != null) {
264						return loadImportType(className);
265					}
266					return inferTypeFromParent(parentSupplier, tag);
267				}
268				return null;
269			}
270	
271			private Class<?> loadImportType(String className) {
272				return loadComponentType(this.modelInterpretationContext.getImport(className));
273			}
274	
275			private @Nullable Class<?> inferTypeFromParent(Supplier<Object> parentSupplier, String tag) {
276				Object parent = parentSupplier.get();
277				if (parent != null) {
278					try {
279						PropertySetter propertySetter = new PropertySetter(
280								this.modelInterpretationContext.getBeanDescriptionCache(), parent);
281						Class<?> typeFromPropertySetter = propertySetter.getClassNameViaImplicitRules(tag,
282								AggregationType.AS_COMPLEX_PROPERTY,
283								this.modelInterpretationContext.getDefaultNestedComponentRegistry());
284						return typeFromPropertySetter;
285					}
286					catch (Exception ex) {
287						return null;
288					}
289				}
290				return null;
291			}
292	
293			private Class<?> loadComponentType(String componentType) {
294				try {
295					return ClassUtils.forName(this.modelInterpretationContext.subst(componentType),
296							getClass().getClassLoader());
297				}
298				catch (Throwable ex) {
299					throw new RuntimeException("Failed to load component type '" + componentType + "'", ex);
300				}
301			}
302	
303			private @Nullable Object instantiate(@Nullable Class<?> type) {
304				if (type == null) {
305					return null;
306				}
307				try {
308					return type.getConstructor().newInstance();
309				}
310				catch (Exception ex) {
311					return null;
312				}
313			}
314	
315			private void processComponent(Class<?> componentType, Set<Class<?>> reflectionTypes) {
316				BeanDescription beanDescription = this.modelInterpretationContext.getBeanDescriptionCache()
317					.getBeanDescription(componentType);
318				reflectionTypes.addAll(parameterTypesNames(beanDescription.getPropertyNameToAdder().values()));
319				reflectionTypes.addAll(parameterTypesNames(beanDescription.getPropertyNameToSetter().values()));
320				reflectionTypes.add(componentType);
321			}
322	
323			private Collection<Class<?>> parameterTypesNames(Collection<Method> methods) {
324				return methods.stream()
325					.filter((method) -> !method.getDeclaringClass().equals(ContextAware.class)
326							&& !method.getDeclaringClass().equals(ContextAwareBase.class))
327					.map(Method::getParameterTypes)
328					.flatMap(Stream::of)
329					.filter((type) -> !type.isPrimitive() && !type.equals(String.class))
330					.map((type) -> type.isArray() ? type.getComponentType() : type)
331					.toList();
332			}
333	
334		}
