337	
338			private Model read() {
339				try (InputStream modelInput = getClass().getClassLoader()
340					.getResourceAsStream(ModelWriter.MODEL_RESOURCE_LOCATION)) {
341					try (ObjectInputStream input = new ObjectInputStream(modelInput)) {
342						Model model = (Model) input.readObject();
343						ModelUtil.resetForReuse(model);
344						markIncludesAsHandled(model);
345						return model;
346					}
347				}
348				catch (Exception ex) {
349					throw new RuntimeException("Failed to load model from '" + ModelWriter.MODEL_RESOURCE_LOCATION + "'",
350							ex);
351				}
352			}
353	
354			private void markIncludesAsHandled(Model model) {
355				if (model instanceof IncludeModel) {
356					model.markAsHandled();
357				}
358				for (Model submodel : model.getSubModels()) {
359					markIncludesAsHandled(submodel);
360				}
361			}
