365		private static final class PatternRules {
366	
367			private static final String RESOURCE_LOCATION = "META-INF/spring/logback-pattern-rules";
368	
369			private final Context context;
370	
371			private PatternRules(Context context) {
372				this.context = context;
373			}
374	
375			private boolean load() {
376				try {
377					ClassPathResource resource = new ClassPathResource(RESOURCE_LOCATION);
378					if (!resource.exists()) {
379						return false;
380					}
381					Properties properties = PropertiesLoaderUtils.loadProperties(resource);
382					Map<String, String> patternRuleRegistry = getRegistryMap();
383					for (String word : properties.stringPropertyNames()) {
384						patternRuleRegistry.put(word, properties.getProperty(word));
385					}
386					return true;
387				}
388				catch (Exception ex) {
389					throw new RuntimeException(ex);
390				}
391			}
392	
393			@SuppressWarnings("unchecked")
394			private Map<String, String> getRegistryMap() {
395				Map<String, String> patternRuleRegistry = (Map<String, String>) this.context
396					.getObject(CoreConstants.PATTERN_RULE_REGISTRY);
397				if (patternRuleRegistry == null) {
398					patternRuleRegistry = new HashMap<>();
399					this.context.putObject(CoreConstants.PATTERN_RULE_REGISTRY, patternRuleRegistry);
400				}
401				return patternRuleRegistry;
402			}
403	
404			private void save(GenerationContext generationContext) {
405				Map<String, String> registryMap = getRegistryMap();
406				byte[] rules = asBytes(registryMap);
407				generationContext.getGeneratedFiles()
408					.handleFile(Kind.RESOURCE, RESOURCE_LOCATION, new RequireNewOrMatchingContentFileHandler(rules));
409				generationContext.getRuntimeHints().resources().registerPattern(RESOURCE_LOCATION);
410				for (String ruleClassName : registryMap.values()) {
411					generationContext.getRuntimeHints()
412						.reflection()
413						.registerType(TypeReference.of(ruleClassName), MemberCategory.INVOKE_PUBLIC_CONSTRUCTORS);
414				}
415			}
416	
417			private byte[] asBytes(Map<String, String> patternRuleRegistry) {
418				Properties properties = CollectionFactory.createSortedProperties(true);
419				patternRuleRegistry.forEach(properties::setProperty);
420				ByteArrayOutputStream bytes = new ByteArrayOutputStream();
421				try {
422					properties.store(bytes, "");
423				}
424				catch (IOException ex) {
425					throw new RuntimeException(ex);
426				}
427				return bytes.toByteArray();
428			}
429	
430		}
