432		private static final class RequireNewOrMatchingContentFileHandler implements ThrowingConsumer<FileHandler> {
433	
434			private final byte[] newContent;
435	
436			private RequireNewOrMatchingContentFileHandler(byte[] newContent) {
437				this.newContent = newContent;
438			}
439	
440			@Override
441			public void acceptWithException(FileHandler file) throws Exception {
442				if (file.exists()) {
443					InputStreamSource content = file.getContent();
444					Assert.state(content != null, "Unable to get file content");
445					byte[] existingContent = content.getInputStream().readAllBytes();
446					if (!Arrays.equals(this.newContent, existingContent)) {
447						throw new IllegalStateException(
448								"Logging configuration differs from the configuration that has already been written. "
449										+ "Update your logging configuration so that it is the same for each context");
450					}
451				}
452				else {
453					file.create(new ByteArrayResource(this.newContent));
454				}
455			}
456	
457		}
